ustify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"For one who is not renounced, the threefold fruits of action – desirable, undesirable and mixed – accrue after death. But those who are in the renounced order of life have no such result to suffer or enjoy.\"}}]}]}]]]}]\n2e:[\"$\",\"div\",\"4500-purport,4500-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L29\",\"child-4505\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"A person in Kṛṣṇa consciousness acting in knowledge of his relationship with Kṛṣṇa is always liberated. Therefore he does not have to enjoy or suffer the results of his acts after death.\"}}]}]]]}]\n33:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":\"lazy\",\"referrerPolicy\":\"no-referrer\",\"crossOrigin\":\"anonymous\"}]]\n"])self.__next_f.push([1,"26:[\"$\",\"div\",null,{\"id\":\"footer\",\"className\":\"mt-auto w-full max-w-7xl mx-auto pt-3 mb-6 text-sm text-vb-normal-text/80 text-center\",\"children\":[[\"$\",\"$L1f\",null,{\"donors\":\"Shweta Saxena; Gopalakrishnan Soundarajan;    Kuldip Persaud;  Raghava Chandra Dasa; Shubhangi Rajiv Panjiyar; Suparna Kotaru;  Rajendra and Geeta Ramchandani;  Jaykumar Prabhakar; Bharat Vyas; Shri Chander Mohan Gilhotra, HG Prashant Mukund Das, Shri Trilok Singh Grover, HG Bhakta Mitra Das, Laxmi Narayan Agarwal; Ronak Talati; Bhargav Ashok; Akiralali; Rajasa das; Riya and Tejal Chopade; Indradyumna Swami; Jai Devaki Parks;  Ashmi Chakraborty; Hari-kirtana da